#pragma once

#include <cstddef>
#include <string>
#include <vector>

struct Prediccion {
    double probabilidad;
    int etiqueta;
};

// Regresion logistica con pesos cargados desde JSON.
// Es inmutable tras cargar: se puede usar desde varios hilos sin sincronizar.
class ModeloLogistico {
public:
    static ModeloLogistico cargar(const std::string& ruta);

    std::size_t num_features() const noexcept { return pesos_.size(); }
    const std::string& version() const noexcept { return version_; }
    const std::vector<std::string>& features() const noexcept { return features_; }

    Prediccion predecir(const std::vector<double>& x) const;

private:
    std::string version_;
    std::vector<std::string> features_;
    std::vector<double> pesos_;
    double sesgo_ = 0.0;
};

#include "model.hpp"

#include <cmath>
#include <fstream>
#include <nlohmann/json.hpp>
#include <stdexcept>

ModeloLogistico ModeloLogistico::cargar(const std::string& ruta) {
    std::ifstream entrada(ruta);
    if (!entrada) {
        throw std::runtime_error("no se pudo abrir el modelo: " + ruta);
    }

    nlohmann::json documento;
    try {
        documento = nlohmann::json::parse(entrada);
    } catch (const nlohmann::json::parse_error& error) {
        throw std::runtime_error(std::string("JSON invalido en el modelo: ") + error.what());
    }

    ModeloLogistico modelo;
    try {
        modelo.version_ = documento.at("version").get<std::string>();
        modelo.features_ = documento.at("features").get<std::vector<std::string>>();
        modelo.pesos_ = documento.at("weights").get<std::vector<double>>();
        modelo.sesgo_ = documento.at("bias").get<double>();
    } catch (const nlohmann::json::exception& error) {
        throw std::runtime_error(std::string("modelo incompleto: ") + error.what());
    }

    if (modelo.pesos_.size() != modelo.features_.size()) {
        throw std::runtime_error("el modelo tiene " + std::to_string(modelo.pesos_.size()) +
                                 " pesos y " + std::to_string(modelo.features_.size()) + " features");
    }
    return modelo;
}

Prediccion ModeloLogistico::predecir(const std::vector<double>& x) const {
    if (x.size() != pesos_.size()) {
        throw std::invalid_argument("se esperaban " + std::to_string(pesos_.size()) +
                                    " features y llegaron " + std::to_string(x.size()));
    }

    double z = sesgo_;
    for (std::size_t i = 0; i < pesos_.size(); ++i) {
        z += pesos_[i] * x[i];
    }

    const double probabilidad = 1.0 / (1.0 + std::exp(-z));
    return {probabilidad, probabilidad >= 0.5 ? 1 : 0};
}

