namespace {

using nlohmann::json;

std::string variable_entorno(const char* nombre, const std::string& por_defecto) {
    const char* valor = std::getenv(nombre);
    return valor != nullptr ? std::string(valor) : por_defecto;
}

void responder_error(httplib::Response& res, int codigo, const std::string& mensaje) {
    res.status = codigo;
    res.set_content(json{{"error", mensaje}}.dump(), "application/json");
}

}  // namespace

int main() {
    const std::string ruta_modelo = variable_entorno("MODELO_PATH", "models/logistic.json");
    const int puerto = std::stoi(variable_entorno("PORT", "8080"));

    ModeloLogistico modelo;
    try {
        modelo = ModeloLogistico::cargar(ruta_modelo);
    } catch (const std::exception& error) {
        std::cerr << "no se pudo cargar el modelo: " << error.what() << "\n";
        return 1;
    }

    std::atomic<long> peticiones{0};
    httplib::Server servidor;

    servidor.set_payload_max_length(64 * 1024);
    servidor.set_read_timeout(5, 0);
    servidor.set_write_timeout(5, 0);

    servidor.Get("/health", [&modelo](const httplib::Request&, httplib::Response& res) {
        res.set_content(json{{"estado", "ok"},
                             {"modelo", modelo.version()},
                             {"features", modelo.num_features()}}
                            .dump(),
                        "application/json");
    });

    servidor.Get("/stats", [&peticiones](const httplib::Request&, httplib::Response& res) {
        res.set_content(json{{"peticiones", peticiones.load()}}.dump(), "application/json");
    });

    servidor.Post("/predict",
                  [&modelo, &peticiones](const httplib::Request& req, httplib::Response& res) {
                      ++peticiones;

                      json cuerpo;
                      try {
                          cuerpo = json::parse(req.body);
                      } catch (const json::parse_error&) {
                          responder_error(res, 400, "el cuerpo no es JSON valido");
                          return;
                      }

                      if (!cuerpo.contains("features") || !cuerpo["features"].is_array()) {
                          responder_error(res, 400, "falta el array 'features'");
                          return;
                      }

                      std::vector<double> x;
                      try {
                          x = cuerpo["features"].get<std::vector<double>>();
                      } catch (const json::type_error&) {
                          responder_error(res, 400, "'features' debe contener solo numeros");
                          return;
                      }

                      try {
                          const Prediccion p = modelo.predecir(x);
                          res.set_content(json{{"probabilidad", p.probabilidad},
                                               {"etiqueta", p.etiqueta},
                                               {"modelo", modelo.version()}}
                                              .dump(),
                                          "application/json");
                      } catch (const std::exception& error) {
                          responder_error(res, 400, error.what());
                      }
                  });

    std::cout << "escuchando en 0.0.0.0:" << puerto << " con modelo " << modelo.version() << "\n";
    if (!servidor.listen("0.0.0.0", puerto)) {
        std::cerr << "no se pudo abrir el puerto " << puerto << "\n";
        return 1;
    }
    return 0;
}

servidor.Post("/predict", [&](const httplib::Request& req, httplib::Response& res) {
    json cuerpo = json::parse(req.body);
    std::vector<double> x = cuerpo["features"].get<std::vector<double>>();
    Prediccion p = modelo.predecir(x);
    res.set_content(json{{"probabilidad", p.probabilidad}}.dump(), "application/json");
});

