#include <cstddef>
#include <iostream>
#include <vector>

#include "model.hpp"

// Aplica el modelo a cada fila del lote.
std::vector<Prediccion> predecir_lote(const ModeloLogistico& modelo,
                                      const std::vector<std::vector<double>>& lote) {
    std::vector<Prediccion> salida;
    salida.reserve(lote.size());
    for (const std::vector<double>& x : lote) {
        salida.push_back(modelo.predecir(x));
    }
    return salida;
}

int main() {
    const ModeloLogistico modelo = ModeloLogistico::cargar("models/logistic.json");
    const std::vector<std::vector<double>> lote{{34, 2500, 4, 1200}, {52, 7000, 15, 300}};

    for (const Prediccion& p : predecir_lote(modelo, lote)) {
        std::cout << "etiqueta=" << p.etiqueta << " p=" << p.probabilidad << '\n';
    }
}

#include <iostream>
#include <mutex>
#include <shared_mutex>
#include <string>
#include <utility>
#include <vector>

#include "model.hpp"

// Envuelve el modelo con un candado de lectura/escritura.
class ModeloServible {
public:
    explicit ModeloServible(const std::string& ruta)
        : modelo_(ModeloLogistico::cargar(ruta)), ruta_(ruta) {}

    Prediccion predecir(const std::vector<double>& x) const {
        const std::shared_lock bloqueo(mutex_);   // muchos lectores a la vez
        return modelo_.predecir(x);
    }

    void recargar() {
        const ModeloLogistico nuevo = ModeloLogistico::cargar(ruta_);  // fuera del candado
        const std::unique_lock bloqueo(mutex_);   // escritor exclusivo, muy breve
        modelo_ = nuevo;
    }

private:
    mutable std::shared_mutex mutex_;
    ModeloLogistico modelo_;
    std::string ruta_;
};

int main() {
    ModeloServible servible("models/logistic.json");
    std::cout << servible.predecir({34, 2500, 4, 1200}).probabilidad << '\n';
    servible.recargar();
    std::cout << servible.predecir({34, 2500, 4, 1200}).probabilidad << '\n';
}
